mapper.select:
SELECT DISTINCT T.TABLENAME
  FROM T_CORE_AT_RECORD_LINE T 
 WHERE T.RECORDID = #{recordId}

SELECT T.TARGETID, T.NEWVALUE AS NAME FROM T_CORE_AT_RECORD_LINE T JOIN ( SELECT MAX(ID) AS ID, TARGETID FROM T_CORE_AT_RECORD_LINE A WHERE A."COLUMN" = #{nameField} AND A.RECORDTYPE != 'DELETE' AND A.TARGETID IN
#{item}
GROUP BY TARGETID ) B ON T.ID = B.ID
